pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Ensure the caller is the authorized address
        vm.assume(_tos.length > 0);
        // Bound v[i] to avoid overflow for large values (safe range)
        for (uint i = 0; i < _tos.length; i++) {
            v[i] = bound(v[i], 0, 1e18);
        }
        // Prank as the authorized sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Call transfer
        c.transfer(_tos, v);
        // Assert that from() returns the expected original address
        assertTrue(c.from() == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    }
}

