pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata _tos, uint[] calldata v) public {
        // Bound the values to match the reference's safe multiplication assumptions
        vm.assume(_tos.length == v.length && _tos.length > 0 && _tos.length <= 10);
        for (uint i = 0; i < v.length; i++) {
            // Ensure v[i] * 1e18 doesn't overflow and is representable
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }
        // Set the msg.sender to the allowed address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool result = c.transfer(_tos, v);
        assertTrue(result, "transfer must return true when not reverting");
    }
}

